fn clamp_score(score: i32, min: i32, max: i32) -> i32 {
    if score < min {
        min
    } else if score > max {
        max
    } else {
        score
    }
}

fn build_summary(project: &Project) -> Result<String, ProjectError> {
    if project.name.is_empty() {
        return Err(ProjectError::MissingName);
    }

    let summary = format!("{}:{}", project.name, project.branch)
        .to_lowercase()
        .replace(' ', "-");

    Ok(summary)
}

fn top_scores(entries: &[Entry]) -> Vec<Entry> {
    let mut ranked = entries.to_vec();
    ranked.sort_by(|a, b| b.score.cmp(&a.score));
    ranked.truncate(5);
    ranked
}

fn group_posts_by_tag(posts: &[Post]) -> HashMap<String, Vec<String>> {
    let mut grouped: HashMap<String, Vec<String>> = HashMap::new();

    for post in posts {
        for tag in &post.tags {
            grouped.entry(tag.clone()).or_default().push(post.slug.clone());
        }
    }

    grouped
}

fn load_config(path: &Path) -> Result<Config, ConfigError> {
    let data = fs::read_to_string(path)
        .map_err(|err| ConfigError::Read(path.to_path_buf(), err))?;

    let config: Config = serde_json::from_str(&data)
        .map_err(ConfigError::Parse)?;

    Ok(config)
}

async fn fetch_with_timeout(client: &Client, url: &str) -> Result<Bytes, FetchError> {
    let response = timeout(Duration::from_secs(5), client.get(url).send())
        .await
        .map_err(|_| FetchError::Timeout)?
        .map_err(FetchError::Request)?;

    response.bytes().await.map_err(FetchError::Body)
}

fn run_workers(jobs: Vec<Job>) -> Vec<Result<Output, JobError>> {
    let handles: Vec<_> = jobs
        .into_iter()
        .map(|job| thread::spawn(move || job.execute()))
        .collect();

    handles
        .into_iter()
        .map(|handle| handle.join().unwrap_or(Err(JobError::Panicked)))
        .collect()
}

pub struct Counter {
    value: Mutex<i64>,
}

impl Counter {
    pub fn new() -> Self {
        Self { value: Mutex::new(0) }
    }

    pub fn increment(&self) {
        let mut guard = self.value.lock().unwrap();
        *guard += 1;
    }

    pub fn value(&self) -> i64 {
        *self.value.lock().unwrap()
    }
}

fn unique_strings(values: &[String]) -> Vec<String> {
    let mut seen = HashSet::with_capacity(values.len());
    let mut unique = Vec::with_capacity(values.len());

    for value in values {
        if seen.insert(value.clone()) {
            unique.push(value.clone());
        }
    }

    unique
}
